const items = $input.all();
const filtered = items.filter(i => i.json.chainId === 'base' || i.json.chainId === 'solana');
return filtered.map(i => ({ json: { chainId: i.json.chainId, tokenAddress: i.json.tokenAddress, profileUrl: i.json.url } }));

const items = $input.all();
const MAX_AGE_H = 48;
const MIN_LIQ = 10000;
const seen = {};

for (const item of items) {
  const pairs = item.json.pairs || [];
  for (const p of pairs) {
    const chain = p.chainId;
    if (chain !== 'base' && chain !== 'solana') continue;
    const liq = parseFloat(p.liquidity && p.liquidity.usd ? p.liquidity.usd : 0);
    if (liq < MIN_LIQ) continue;
    const now = Date.now();
    const created = p.pairCreatedAt || now;
    const ageMs = now - created;
    const ageH = Math.floor(ageMs / 3600000);
    if (ageH > MAX_AGE_H) continue;
    const ageM = Math.floor((ageMs % 3600000) / 60000);
    const ageStr = ageH > 0 ? ageH + 'h ' + ageM + 'm' : ageM + 'm';
    const address = p.baseToken && p.baseToken.address ? p.baseToken.address : '';
    const buys5m = p.txns && p.txns.m5 ? p.txns.m5.buys : 0;
    const sells5m = p.txns && p.txns.m5 ? p.txns.m5.sells : 0;
    const total5m = buys5m + sells5m;
    const buyPct = total5m > 0 ? Math.round((buys5m / total5m) * 100) : 0;
    const buys1h = p.txns && p.txns.h1 ? p.txns.h1.buys : 0;
    const sells1h = p.txns && p.txns.h1 ? p.txns.h1.sells : 0;
    const token = {
      chain: chain,
      name: p.baseToken && p.baseToken.name ? p.baseToken.name : 'Unknown',
      symbol: p.baseToken && p.baseToken.symbol ? p.baseToken.symbol : '?',
      address: address,
      pairAddress: p.pairAddress || '',
      dex: p.dexId || '',
      priceUsd: p.priceUsd || '0',
      liquidity: liq,
      marketCap: p.marketCap || 0,
      fdv: p.fdv || 0,
      volume5m: p.volume && p.volume.m5 ? p.volume.m5 : 0,
      volume1h: p.volume && p.volume.h1 ? p.volume.h1 : 0,
      volume6h: p.volume && p.volume.h6 ? p.volume.h6 : 0,
      priceChange5m: p.priceChange && p.priceChange.m5 ? p.priceChange.m5 : 0,
      priceChange1h: p.priceChange && p.priceChange.h1 ? p.priceChange.h1 : 0,
      priceChange6h: p.priceChange && p.priceChange.h6 ? p.priceChange.h6 : 0,
      buys1h: buys1h,
      sells1h: sells1h,
      buys5m: buys5m,
      sells5m: sells5m,
      buyPct5m: buyPct,
      age: ageStr,
      pairCreatedAt: p.pairCreatedAt ? new Date(p.pairCreatedAt).toISOString() : '',
      url: p.url || ''
    };
    if (seen[address]) {
      if (liq > seen[address].liquidity) seen[address] = token;
    } else {
      seen[address] = token;
    }
  }
}

const sorted = Object.values(seen).sort(function(a, b) { return b.liquidity - a.liquidity; });
return sorted.map(function(t) { return { json: t }; });

const items = $input.all();
if (items[0].json.empty) return items;
return items.map(i => ({ json: Object.assign({}, i.json, { goplusChain: i.json.chain === 'solana' ? 'solana' : '8453' }) }));

const goplusItems = $('GoPlus Security Check').all();
const tokenItems = $('Prep GoPlus').all();
const rugcheckItems = $('RugCheck').all();
const honeypotItems = $('Honeypot.is').all();
if (goplusItems[0].json.empty) return goplusItems;

const results = goplusItems.map(function(item, idx) {
  const token = tokenItems[idx] ? tokenItems[idx].json : {};
  const gpData = item.json;
  const rcData = rugcheckItems[idx] ? rugcheckItems[idx].json : {};
  const hpData = honeypotItems[idx] ? honeypotItems[idx].json : {};
  const safetyFlags = [];
  var holderCount = 0;

  // enriched fields passed to Build Prompt
  var top1Pct = 0, top5Pct = 0, creatorPct = 0, lpLocked = false, lpBurned = false;
  var lpProviderCount = 0, totalHolders = 0, insiderCount = 0;
  var insiderNetworkSummary = '', launchpad = '', creatorBalance = 0;
  var topHolderLines = [];

  // --- GoPlus ---
  try {
    const gpResult = gpData.result || {};
    const keys = Object.keys(gpResult);
    const gp = keys.length > 0 ? gpResult[keys[0]] : {};
    holderCount = parseInt(gp.holder_count || 0);

    // existing flags
    if (gp.is_honeypot === '1') safetyFlags.push('HONEYPOT');
    if (gp.is_blacklisted === '1') safetyFlags.push('BLACKLISTED');
    if (gp.is_mintable === '1') safetyFlags.push('MINTABLE');
    if (gp.owner_change_balance === '1') safetyFlags.push('OWNER_CAN_CHANGE_BALANCE');
    if (parseFloat(gp.buy_tax || 0) > 10) safetyFlags.push('HIGH_BUY_TAX');
    if (parseFloat(gp.sell_tax || 0) > 10) safetyFlags.push('HIGH_SELL_TAX');
    if (holderCount > 0 && holderCount < 10) safetyFlags.push('FEW_HOLDERS');

    // new: hard fails
    if (gp.hidden_owner === '1') safetyFlags.push('HIDDEN_OWNER');
    if (gp.can_take_back_ownership === '1') safetyFlags.push('CAN_RECLAIM_OWNERSHIP');
    if (gp.honeypot_with_same_creator === '1') safetyFlags.push('CREATOR_HONEYPOT_HISTORY');

    // new: enrichment
    creatorPct = parseFloat(gp.creator_percent || 0);
    lpProviderCount = parseInt(gp.lp_holder_count || 0);

    const holders = gp.holders || [];
    if (holders.length > 0) {
      top1Pct = Math.round(parseFloat(holders[0].percent || 0) * 100 * 10) / 10;
      top5Pct = Math.round(holders.slice(0, 5).reduce(function(s, h) { return s + parseFloat(h.percent || 0) * 100; }, 0) * 10) / 10;
    }
    if (top1Pct > 40) safetyFlags.push('WHALE_CONCENTRATION');

    const lpHolders = gp.lp_holders || [];
    lpLocked = lpHolders.some(function(h) { return h.is_locked === 1 || h.is_locked === '1'; });
  } catch(e) {}

  // --- RugCheck (Solana only) ---
  var rcScore = null;
  if (token.chain === 'solana') {
    try {
      const risks = rcData.risks || [];
      for (const r of risks) {
        const name = (r.name || '').toUpperCase();
        const level = (r.level || '').toUpperCase();
        if (name.includes('HONEYPOT') || (name.includes('FREEZE') && level === 'DANGER')) safetyFlags.push('RC_HONEYPOT');
        if (name.includes('MINT') && level === 'DANGER') safetyFlags.push('RC_MINTABLE');
        if (name.includes('RUGPULL') || name.includes('RUG')) safetyFlags.push('RC_RUGPULL');
      }
      rcScore = rcData.score_normalised !== undefined ? rcData.score_normalised : null;
      if (rcScore !== null && rcScore < 20) safetyFlags.push('RC_LOW_SCORE');

      // new: enrichment
      totalHolders = rcData.totalHolders || 0;
      lpProviderCount = rcData.totalLPProviders || 0;
      insiderCount = rcData.graphInsidersDetected || 0;
      creatorBalance = rcData.creatorBalance || 0;
      launchpad = (rcData.launchpad || {}).name || '';

      const insiderNets = rcData.insiderNetworks || [];
      if (insiderNets.length > 0) {
        const net = insiderNets[0];
        insiderNetworkSummary = net.size + ' wallets / ' + net.activeAccounts + ' active / type:' + net.type;
      }

      const markets = rcData.markets || [];
      if (markets.length > 0) {
        const lp = markets[0].lp || {};
        lpBurned = lp.lpBurned === true;
        lpLocked = lpLocked || (lp.lpCurrentSupply !== undefined && lp.lpCurrentSupply > 0 && !lpBurned);
      }

      const topH = (rcData.topHolders || []).slice(0, 5);
      if (topH.length > 0) {
        top1Pct = Math.round(topH[0].pct * 10) / 10;
        top5Pct = Math.round(topH.slice(0,5).reduce(function(s,h){return s+h.pct;},0) * 10) / 10;
        topHolderLines = topH.map(function(h) {
          return Math.round(h.pct * 10)/10 + '% ' + (h.insider ? '[INSIDER]' : '');
        });
      }
      if (top1Pct > 40) safetyFlags.push('WHALE_CONCENTRATION');
    } catch(e) {}
  }

  // --- Honeypot.is (Base only) ---
  if (token.chain === 'base') {
    try {
      if (hpData.honeypotResult && hpData.honeypotResult.isHoneypot === true) safetyFlags.push('HONEYPOT');
      const sim = hpData.simulationResult || {};
      if (parseFloat(sim.buyTax || 0) > 10) safetyFlags.push('HIGH_BUY_TAX');
      if (parseFloat(sim.sellTax || 0) > 10) safetyFlags.push('HIGH_SELL_TAX');
      if (sim.isOpenSource === false) safetyFlags.push('UNVERIFIED_CONTRACT');
      const flags = hpData.flags || [];
      if (flags.some(function(f) { return (f || '').toLowerCase().includes('control'); })) safetyFlags.push('CREATOR_CONTROL');
      if (hpData.contractCode && hpData.contractCode.isOpenSource === false) safetyFlags.push('UNVERIFIED_CONTRACT');
    } catch(e) {}
  }

  const uniqueFlags = [...new Set(safetyFlags)];
  const hardFails = ['HONEYPOT', 'RC_HONEYPOT', 'BLACKLISTED', 'HIDDEN_OWNER', 'CAN_RECLAIM_OWNERSHIP', 'CREATOR_HONEYPOT_HISTORY'];
  const safe = !uniqueFlags.some(function(f) { return hardFails.indexOf(f) !== -1; });
  const riskLevel = uniqueFlags.length === 0 ? 'LOW' : uniqueFlags.length <= 2 ? 'MEDIUM' : 'HIGH';

  return { json: Object.assign({}, token, {
    holderCount: totalHolders || holderCount,
    safetyFlags: uniqueFlags,
    safe: safe,
    riskLevel: riskLevel,
    top1Pct: top1Pct,
    top5Pct: top5Pct,
    creatorPct: creatorPct,
    creatorBalance: creatorBalance,
    lpLocked: lpLocked,
    lpBurned: lpBurned,
    lpProviderCount: lpProviderCount,
    insiderCount: insiderCount,
    insiderNetworkSummary: insiderNetworkSummary,
    launchpad: launchpad,
    topHolderLines: topHolderLines,
    rcScore: rcScore
  })};
});

return results.filter(function(r) { return r.json.safe; });

const items = $input.all();
if (items[0].json.empty) return items;

function calcScenarios(priceUsd) {
  const p = parseFloat(priceUsd);
  if (!p || p === 0) return null;
  const fmt = function(v) {
    if (v < 0.00001) return '$' + v.toExponential(3);
    if (v < 0.001) return '$' + v.toFixed(7);
    if (v < 1) return '$' + v.toFixed(5);
    return '$' + v.toFixed(4);
  };
  return {
    agg:  { entry: fmt(p),        target: fmt(p * 1.18), stop: fmt(p * 0.90) },
    cons: { entry: fmt(p * 0.95), target: fmt(p * 0.95 * 1.15), stop: fmt(p * 0.95 * 0.92) }
  };
}

function parseAgeMinutes(ageStr) {
  var m = 0;
  var hMatch = (ageStr || '').match(/(\d+)h/);
  var mMatch = (ageStr || '').match(/(\d+)m/);
  if (hMatch) m += parseInt(hMatch[1]) * 60;
  if (mMatch) m += parseInt(mMatch[1]);
  return m;
}

// Pre-filter: age, micro-trend, AND chain-specific V/L ceiling (hard rules, no LLM override)
// Solana: V/L flat ceiling ≤4x (6-8x re-admission was a mistake — unbiased data shows it's -0.56% avg)
// Solana: also excludes 'flat' micro-trend (n=662, -1.47% avg, 27.5% win in filter-pass — pure noise)
const freshItems = items.filter(function(item) {
  const ageMin = parseAgeMinutes(item.json.age);
  const micro = item.json.microTrend || '';
  const liq = item.json.liquidity || 0;
  const vl = liq > 0 ? item.json.volume1h / liq : 0;
  const chain = item.json.chain;
  const vlPass = chain === 'solana'
    ? (vl <= 4.0)
    : (vl <= 8.0);
  const microPass = chain === 'solana'
    ? ((micro !== 'recovering' || item.json.volTrend === 'rising') && micro !== 'down' && micro !== 'flat')
    : (micro !== 'recovering' && micro !== 'down');
  return ageMin >= 15 && ageMin <= 90 && microPass && vlPass;
});
const staleCount = items.length - freshItems.length;

// Short-circuit: nothing passed filters — skip the LLM call entirely
if (freshItems.length === 0) {
  const css = 'body{font-family:system-ui,sans-serif;background:#1a1a1a;color:#e8e8e8;margin:0 auto;padding:40px;max-width:800px;}h1{color:#fff;border-bottom:1px solid #444;padding-bottom:8px;}.info{background:#1e2a2a;border:1px solid #3a5a5a;border-radius:8px;padding:1.5rem;color:#aaa;margin-top:1.5rem;}.ts{color:#aaa;font-size:.85rem;}';
  const ts = new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
  const noun = items.length === 1 ? 'token' : 'tokens';
  const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>DEX Scanner</title><style>' + css + '</style></head>'
    + '<body><h1>DEX Scanner</h1>'
    + '<p class="ts">' + ts + ' &nbsp;&bull;&nbsp; ' + items.length + ' launches &nbsp;&bull;&nbsp; ' + items.length + ' pre-filtered &nbsp;&bull;&nbsp; Base + Solana &nbsp;&bull;&nbsp; $10k+ liq &nbsp;&bull;&nbsp; honeypots removed</p>'
    + '<div class="info">All ' + items.length + ' ' + noun + ' in this batch were pre-filtered (age out of window, low momentum, or V/L ratio exceeded) — nothing to analyze.</div>'
    + '</body></html>';
  return [{ json: { empty: true, emptyReason: 'all_filtered', staleCount: staleCount, tokenCount: items.length, html: html } }];
}

const lines = freshItems.map(function(item, i) {
  const t = item.json;

  // signal eligibility gate
  const vlRatio = t.liquidity > 0 ? t.volume1h / t.liquidity : 0;
  const ineligible = [];
  if (t.priceChange1h < -15) ineligible.push('1h drop ' + t.priceChange1h + '% < -15%');
  if (t.volTrend === 'falling' && (t.microTrend === 'down' || t.microTrend === 'fading')) {
    ineligible.push('vol falling + micro ' + t.microTrend);
  }
  if (t.buyPct5m < 55) ineligible.push('5m buy pressure ' + t.buyPct5m + '% < 55%');
  // V/L ceiling enforced in pre-filter above; keep low-end check only
  if (vlRatio < 0.3) ineligible.push('V/L ' + vlRatio.toFixed(2) + 'x too low');
  const eligNote = ineligible.length > 0
    ? '[SIGNAL WARNINGS (' + ineligible.length + '): ' + ineligible.join('; ') + ']\n   '
    : '';

  // ML-validated derived signals
  const liqMcapRatio = (t.liquidity > 0 && t.marketCap > 0)
    ? (t.liquidity / t.marketCap).toFixed(3) : null;
  const vol5m1hRatio = t.volume1h > 0 ? (t.volume5m * 12 / t.volume1h) : null;
  const momentumScore = (vol5m1hRatio !== null && t.priceChange5m != null)
    ? (t.priceChange5m * Math.min(vol5m1hRatio, 10.0)).toFixed(2) : null;

  const flags = t.safetyFlags.length > 0 ? 'FLAGS: ' + t.safetyFlags.join(', ') : 'Clean';
  const c5m = t.priceChange5m > 0 ? '+' + t.priceChange5m : '' + t.priceChange5m;
  const c1h = t.priceChange1h > 0 ? '+' + t.priceChange1h : '' + t.priceChange1h;
  const c6h = t.priceChange6h > 0 ? '+' + t.priceChange6h : '' + t.priceChange6h;
  const mcap = t.marketCap > 0 ? '$' + Math.round(t.marketCap).toLocaleString() : 'unknown';

  // distribution intel
  const holderLine = t.holderCount > 0
    ? 'Holders: ' + t.holderCount + ' total'
      + (t.top1Pct > 0 ? ' | Top1: ' + t.top1Pct + '%' : '')
      + (t.top5Pct > 0 ? ' | Top5: ' + t.top5Pct + '%' : '')
      + (t.creatorBalance === 0 && t.creatorPct === 0 ? ' | Creator: 0% (good)' : t.creatorPct > 0 ? ' | Creator holds: ' + t.creatorPct.toFixed(1) + '%' : '')
    : '';

  const insiderLine = t.insiderCount > 0
    ? 'Insiders: ' + t.insiderCount + ' detected' + (t.insiderNetworkSummary ? ' (' + t.insiderNetworkSummary + ')' : '')
    : '';

  const lpLine = t.chain === 'solana'
    ? 'LP: ' + (t.lpBurned ? 'BURNED (safe)' : t.lpLocked ? 'locked' : 'UNLOCKED')
      + ' | LP providers: ' + (t.lpProviderCount || 0)
      + (t.launchpad ? ' | Platform: ' + t.launchpad : '')
      + (t.rcScore !== null ? ' | RugScore: ' + t.rcScore + '/100' : '')
    : 'LP providers: ' + (t.lpProviderCount || 0) + (t.lpLocked ? ' (locked)' : t.lpBurned ? ' (burned)' : ' (unlocked)');

  const volTrendStr = t.volTrend && t.volTrend !== 'unknown'
    ? 'Vol trend: ' + t.volTrend + ' (' + (t.volTrendPct > 0 ? '+' : '') + t.volTrendPct + '%) | Micro: ' + t.microTrend
    : '';

  const sc = calcScenarios(t.priceUsd);
  const scenarioLine = sc
    ? '\n   Scenarios — Aggressive: entry ' + sc.agg.entry + ', target ' + sc.agg.target + ' (+18%), stop ' + sc.agg.stop + ' (-10%) | Conservative: entry ' + sc.cons.entry + ' (-5% dip), target ' + sc.cons.target + ' (+15%), stop ' + sc.cons.stop + ' (-8%)'
    : '';

  const inflowLabel = t.chain === 'base' && t.netInflowUsd > 20000
    ? ' *** STRONG BASE INFLOW — +25% avg signal ***'
    : t.netInflowUsd > 0 ? ' (net buyers)' : t.netInflowUsd < 0 ? ' (net sellers)' : ' (neutral)';

  return (i+1) + '. ' + t.name + ' (' + t.symbol + ') - ' + t.chain.toUpperCase() + ' via ' + t.dex
    + '\n   ' + eligNote
    + 'Contract: ' + t.address
    + '\n   Age: ' + t.age + ' | Risk: ' + t.riskLevel + ' | ' + flags
    + '\n   Price: $' + parseFloat(t.priceUsd).toFixed(8) + ' | MCap: ' + mcap + ' | Liq: $' + Math.round(t.liquidity).toLocaleString()
    + '\n   5m: ' + c5m + '% | 1h: ' + c1h + '% | 6h: ' + c6h + '%'
    + '\n   Vol5m: $' + Math.round(t.volume5m).toLocaleString() + ' | Vol1h: $' + Math.round(t.volume1h).toLocaleString()
    + (liqMcapRatio ? '\n   Liq/MCap: ' + liqMcapRatio + 'x' + (momentumScore ? ' | Momentum score: ' + momentumScore : '') : '')
    + '\n   Buys/Sells 1h: ' + t.buys1h + '/' + t.sells1h + ' | 5m buy pressure: ' + t.buyPct5m + '%'
    + (volTrendStr ? '\n   ' + volTrendStr : '')
    + (holderLine ? '\n   ' + holderLine : '')
    + (insiderLine ? '\n   ' + insiderLine : '')
    + '\n   ' + lpLine
    + (t.uniqueTraders1h != null ? '\n   Traders 1h: ' + t.uniqueTraders1h + ' | Net inflow 1h: $' + (t.netInflowUsd > 0 ? '+' : '') + (t.netInflowUsd || 0).toLocaleString() + inflowLabel : '')
    + scenarioLine
    + '\n   ' + t.url;
});

const system = 'You are a meme coin trader with years of experience on Solana and Base DEXes. You have seen thousands of launches and can read a pump from a trap within seconds.\n\nThese tokens already passed automated safety and signal filters. Do NOT re-evaluate the numbers — the filters handle that. Your job is to read what the numbers cannot tell you.\n\nFor each token answer three things:\n1. LIFECYCLE: Where is this in the pump cycle? Early discovery / active momentum building / topping / already dead?\n2. PATTERN: Does this look like organic degen energy or manufactured hype / exit liquidity? Read the holder distribution, insider count, launch platform, buy pattern, and age together as a story.\n3. CONVICTION: Given everything, size it — would you risk $50? $500? Nothing? One sentence why.\n\nFormat: N. SYMBOL — SKIP/WATCH/INTERESTING — [conviction: $X or nothing] — one sentence.\nFor INTERESTING only: add a second line with the pre-calculated scenarios copied exactly from the input.\nFor WATCH: add a second line on what would flip it to INTERESTING.\n\nRatings:\n- INTERESTING: real momentum, distribution looks organic, narrative or launch context has legs, you would risk $100–500\n- WATCH: mixed signals or too early to confirm — worth a $25–50 probe or checking again in 5–10 min\n- SKIP: concentration red flags, exit liquidity pattern, no narrative, manufactured volume, or the move is already done\n\nMeme coin context to apply:\n- Pump.Fun graduation = LP is burned, bonding curve closed — lower rug risk, specific entry dynamic\n- High insider count + concentrated top holders = cabal likely front-running you — be skeptical\n- Holder count growing fast relative to age = real FOMO building — bullish signal\n- Vertical 1h spike already happened = you are the exit liquidity — skip\n- Creator holds 0% = good (fair launch or moved on); creator holds >5% = watch them\n- Locked/burned LP = safety floor exists, real commitment\n- Strong net inflow on Base (marked *** STRONG BASE INFLOW ***) = retail actually buying — meaningful signal\n- SIGNAL WARNINGS in the data = filter borderline cases — factor into conviction sizing, not automatic skip\n\nML-CALIBRATED SIGNALS (from 25,000+ unbiased observations, 14 days):\n- Base: buys_5m (raw 5m buy count) and Liq/MCap ratio are the top predictors of >=20% moves. High buys_5m + Liq/MCap < 0.3 = maximum conviction setup. Fading micro-trend on Base often precedes a surge — treat as consolidation, not decay.\n- Solana: volume_5m dollar magnitude and Liq/MCap ratio dominate. Volume spike with Liq/MCap < 0.3 = strongest Solana signal. Focus on volume magnitude, not VL ratio (already pre-filtered).\n- Both chains: rising vol_trend + low Liq/MCap is the cleanest observed pattern. Momentum score (shown when available) combines price velocity with volume acceleration — large positive reinforces INTERESTING; near-zero or negative argues WATCH/SKIP.';

const user = 'Analyze these DEX token launches. Tokens passed automated filters — your job is meme coin conviction assessment, not signal re-evaluation.\n\n' + lines.join('\n\n');

return [{ json: { system: system, user: user, tokenCount: items.length, staleCount: staleCount, freshCount: freshItems.length, tokens: freshItems.map(function(i) { return i.json; }) } }];

const items = $input.all();
if (items[0].json.empty) {
  if (items[0].json.html) return [{ json: { html: items[0].json.html } }];
  return items;
}
const llm = items[0].json;
const analysis = (llm.choices && llm.choices[0] && llm.choices[0].message ? llm.choices[0].message.content : 'Analysis unavailable').replace(/<\|im_end\|>|<\|im_start\|>/g, '').trim();
const buildNode = $('Build Prompt').all()[0].json;
const tokenCount = buildNode.tokenCount || 0;
const staleCount = buildNode.staleCount || 0;
const freshCount = buildNode.freshCount || 0;
const tokens = buildNode.tokens || [];

// All tokens pre-filtered: LLM was never called, use the pre-built HTML from Build Prompt
if (buildNode.empty && buildNode.html) {
  return [{ json: { html: buildNode.html } }];
}
const timestamp = new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });

function parseRatings(text) {
  const map = {};
  const re = /^(\d+)\.\s+\S+\s*[—–\-]+\s*(SKIP|WATCH|INTERESTING)/gim;
  var m;
  while ((m = re.exec(text)) !== null) {
    map[parseInt(m[1]) - 1] = m[2].toUpperCase();
  }
  return map;
}

const ratingMap = parseRatings(analysis);
const ratedTokens = tokens.map(function(t, i) {
  return Object.assign({}, t, { rating: ratingMap[i] || 'SKIP' });
});
const skipCount = ratedTokens.filter(function(t) { return t.rating === 'SKIP'; }).length;
const visibleTokens = ratedTokens
  .filter(function(t) { return t.rating !== 'SKIP'; })
  .sort(function(a, b) {
    const order = { INTERESTING: 0, WATCH: 1 };
    const ao = order[a.rating] !== undefined ? order[a.rating] : 2;
    const bo = order[b.rating] !== undefined ? order[b.rating] : 2;
    return ao - bo;
  });
const interestingCount = visibleTokens.filter(function(t) { return t.rating === 'INTERESTING'; }).length;
const watchCount = visibleTokens.filter(function(t) { return t.rating === 'WATCH'; }).length;

function mdToHtml(text) {
  return text
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/\*\*INTERESTING\*\*/g, '<span class="interesting">INTERESTING</span>')
    .replace(/\*\*WATCH\*\*/g, '<span class="watch">WATCH</span>')
    .replace(/\*\*SKIP\*\*/g, '<span class="skip">SKIP</span>')
    .replace(/INTERESTING/g, '<span class="interesting">INTERESTING</span>')
    .replace(/\bWATCH\b/g, '<span class="watch">WATCH</span>')
    .replace(/\bSKIP\b/g, '<span class="skip">SKIP</span>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/### (.*)/g, '<h3>$1</h3>')
    .replace(/## (.*)/g, '<h2>$1</h2>')
    .replace(/^(\d+)\. /gm, '<br><span class="num">$1.</span> ')
    .replace(/\n- /g, '<br>&bull; ')
    .replace(/(<br>)(  |&nbsp;&nbsp;)(Aggressive|Conservative):/g, '$1<span class="scenario"><strong>$3:</strong>')
    .replace(/\n/g, '<br>');
}

function renderCard(t) {
