    ? 'https://basescan.org/token/' + t.address
    : 'https://solscan.io/token/' + t.address;
  const explorerLabel = t.chain === 'base' ? 'BaseScan' : 'Solscan';
  const deepDiveUrl = 'http://192.168.33.231:5678/webhook/dex-deep-dive?token=' + t.address + '&chain=' + t.chain;
  const ratingBadge = t.rating === 'INTERESTING'
    ? '<span class="badge-interesting">INTERESTING</span>'
    : '<span class="badge-watch">WATCH</span>';
  let streakBadge = '';
  if (t.streak && t.streak.appearances > 1) {
    const prev = t.streak.prevRating;
    const upgraded = prev && prev !== 'INTERESTING' && t.rating === 'INTERESTING';
    const downgraded = prev && prev === 'INTERESTING' && t.rating !== 'INTERESTING';
    const arrow = upgraded ? ' ↑' : downgraded ? ' ↓' : '';
    const prevTxt = (prev && prev !== t.rating) ? ' · was ' + prev : '';
    streakBadge = '<span class="badge-streak">' + t.streak.appearances + '×' + arrow + prevTxt + ' · ' + t.streak.minutesSinceFirst + 'm</span>';
  }
  const cardClass = t.rating === 'INTERESTING' ? 'card card-interesting' : 'card';
  return '<div class="' + cardClass + '">'
    + '<div class="card-header">'
    + '<span class="tname">' + t.name + ' <span class="sym">(' + t.symbol + ')</span></span>'
    + '<div class="card-header-right"><span class="chain-tag chain-' + t.chain + '">' + t.chain.toUpperCase() + '</span><span class="dex-tag">' + t.dex + '</span>' + ratingBadge + streakBadge + '</div>'
