    + '<span class="label">Age</span><span>' + t.age + '</span>'
    + '<span class="label">Liq</span><span>$' + Math.round(t.liquidity).toLocaleString() + '</span>'
    + '<span class="label">MCap</span><span>$' + Math.round(t.marketCap).toLocaleString() + '</span>'
    + '</div>'
    + '<div class="card-row">'
    + '<span class="label">5m</span><span class="' + col(t.priceChange5m) + '">' + fmt(t.priceChange5m) + '</span>'
    + '<span class="label">1h</span><span class="' + col(t.priceChange1h) + '">' + fmt(t.priceChange1h) + '</span>'
    + '<span class="label">6h</span><span class="' + col(t.priceChange6h) + '">' + fmt(t.priceChange6h) + '</span>'
    + '</div>'
    + '<div class="card-row">'    + '<span class="label">Buys/Sells 1h</span><span>' + t.buys1h + '/' + t.sells1h + '</span>'    + '<span class="label">Buy% 5m</span><span class="' + (t.buyPct5m >= 55 ? 'pos' : 'neg') + '">' + t.buyPct5m + '%</span>'    + '</div>'    + (t.uniqueTraders1h != null ? '<div class="card-row">'    + '<span class="label">Traders 1h</span><span>' + t.uniqueTraders1h + '</span>'    + '<span class="label">Net Inflow</span><span class="' + (t.netInflowUsd > 0 ? 'pos' : t.netInflowUsd < 0 ? 'neg' : 'flat') + '">'    + (t.netInflowUsd > 0 ? '+' : '') + '$' + Math.abs(t.netInflowUsd || 0).toLocaleString()    + '</span></div>' : '')
    + (t.sparkline ? '<div class="sparkline" title="price shape (6h→1h→5m)">' + t.sparkline + '</div>' : '')
    + '<div class="vol-trend">Vol: <span class="' + (t.volTrend === 'rising' ? 'pos' : t.volTrend === 'falling' ? 'neg' : 'flat') + '">' + (t.volTrend || 'n/a') + (t.volTrendPct ? ' (' + (t.volTrendPct > 0 ? '+' : '') + t.volTrendPct + '%)' : '') + '</span> &nbsp; Micro: <span class="' + (t.microTrend === 'up' ? 'pos' : t.microTrend === 'down' ? 'neg' : 'flat') + '">' + (t.microTrend || 'n/a') + '</span></div>'
