  const llmOutput = $('LLM Analysis').all()[0].json;
  const content = (llmOutput.choices && llmOutput.choices[0] && llmOutput.choices[0].message)
    ? llmOutput.choices[0].message.content : '';

  const ratingMap = {};
  const re = /^(\d+)\.\s+\S+\s*[—–\-]+\s*(SKIP|WATCH|INTERESTING)/gim;
  let m;
  while ((m = re.exec(content)) !== null) {
    ratingMap[parseInt(m[1]) - 1] = m[2].toUpperCase();
  }

  const staticData = $getWorkflowStaticData('global');
  if (!staticData.tokenState) staticData.tokenState = {};
  const state = staticData.tokenState;

  const now = new Date().toISOString();

  tokens.forEach((t, i) => {
    const addr = t.address;
    if (!addr) return;
    const rating = ratingMap[i] || 'SKIP';
    if (state[addr]) {
      state[addr].appearances++;
      state[addr].ratingHistory.push(rating);
      if (state[addr].ratingHistory.length > 20) state[addr].ratingHistory = state[addr].ratingHistory.slice(-20);
      state[addr].lastSeen = now;
    } else {
      state[addr] = { firstSeen: now, lastSeen: now, appearances: 1, ratingHistory: [rating], symbol: t.symbol, name: t.name };
    }
  });

  // Prune tokens not seen in last 3 hours
  const cutoff = Date.now() - 3 * 60 * 60 * 1000;
  for (const addr of Object.keys(state)) {
    if (new Date(state[addr].lastSeen).getTime() < cutoff) delete state[addr];
  }

  staticData.tokenState = state;
} catch(e) {
  // Never block the response on state errors
}

