function mdToHtml(text) {
  return text
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/\*\*INTERESTING\*\*/g, '<span class="interesting">INTERESTING</span>')
    .replace(/\*\*WATCH\*\*/g, '<span class="watch">WATCH</span>')
    .replace(/\*\*SKIP\*\*/g, '<span class="skip">SKIP</span>')
    .replace(/INTERESTING/g, '<span class="interesting">INTERESTING</span>')
    .replace(/\bWATCH\b/g, '<span class="watch">WATCH</span>')
    .replace(/\bSKIP\b/g, '<span class="skip">SKIP</span>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/### (.*)/g, '<h3>$1</h3>')
    .replace(/## (.*)/g, '<h2>$1</h2>')
    .replace(/^(\d+)\. /gm, '<br><span class="num">$1.</span> ')
    .replace(/\n- /g, '<br>&bull; ')
    .replace(/(<br>)(  |&nbsp;&nbsp;)(Aggressive|Conservative):/g, '$1<span class="scenario"><strong>$3:</strong>')
    .replace(/\n/g, '<br>');
}

