const items = $input.all();

return items.map(function(item) {
  const t = item.json;

  // Volume trend: compare current 5m pace vs 1h average pace
  // vol5m * 12 = projected vol/hr at current rate
  // vol1h = actual last hour vol
  var volTrend = 'n/a';
  var volTrendPct = 0;
  var microTrend = 'n/a';
  var sparkline = '';

  const v5m = parseFloat(t.volume5m) || 0;
  const v1h = parseFloat(t.volume1h) || 0;
  const v6h = parseFloat(t.volume6h) || 0;

  if (v5m > 0 && v1h > 0) {
    const projectedHourly = v5m * 12;
    const avgHourly = v1h; // last 1h actual
    volTrendPct = Math.round(((projectedHourly - avgHourly) / avgHourly) * 100);
    volTrend = volTrendPct >= 30 ? 'rising' : volTrendPct <= -30 ? 'falling' : 'flat';
  }

  // Micro trend from price changes: 5m vs 1h direction
  const p5m = parseFloat(t.priceChange5m) || 0;
  const p1h = parseFloat(t.priceChange1h) || 0;
  const p6h = parseFloat(t.priceChange6h) || 0;

  if (p5m > 2 && p1h > 0) microTrend = 'up';
  else if (p5m < -2 && p1h < 0) microTrend = 'down';
  else if (p5m > 2 && p1h < 0) microTrend = 'recovering';
  else if (p5m < -2 && p1h > 0) microTrend = 'fading';
  else microTrend = 'flat';

  // Simple ASCII sparkline from % changes we have (5m, 1h, 6h)
  // Not a real chart but gives shape: start → 6h → 1h → now
  const points = [0, p6h, p1h, p5m];
  const mn = Math.min(...points), mx = Math.max(...points);
  const range = mx - mn;
  const blocks = ['▁','▂','▃','▄','▅','▆','▇','█'];
  if (range > 0) {
    sparkline = points.map(function(p) {
      return blocks[Math.min(7, Math.floor(((p - mn) / range) * 8))];
    }).join('');
  }

  return { json: Object.assign({}, t, {
    sparkline: sparkline,
    volTrend: volTrend,
    volTrendPct: volTrendPct,
    microTrend: microTrend
  })};
});

