    liquidity_usd: t.liquidity ? parseFloat(t.liquidity) : null,
    volume_1h:    t.volume1h ? parseFloat(t.volume1h) : null,
    volume_5m:    t.volume5m ? parseFloat(t.volume5m) : null,
    price_ch_5m:  t.priceChange5m != null ? parseFloat(t.priceChange5m) : null,
    price_ch_1h:  t.priceChange1h != null ? parseFloat(t.priceChange1h) : null,
    price_ch_6h:  t.priceChange6h != null ? parseFloat(t.priceChange6h) : null,
    buy_pct_5m:   t.buyPct5m != null ? parseFloat(t.buyPct5m) : null,
    buy_pct_1h:   t.buyPct1h != null ? parseFloat(t.buyPct1h) : null,
    vl_ratio:     vlRatio,
    vol_trend:    t.volTrend || null,
    micro_trend:  t.microTrend || null,
    flags:        Array.isArray(t.safetyFlags) ? t.safetyFlags.join(',') : (t.safetyFlags || ''),
    reasoning:    reasonMap[i] || null,
    unique_traders_1h: t.uniqueTraders1h != null ? parseInt(t.uniqueTraders1h) : null,
    net_inflow_usd:    t.netInflowUsd != null ? parseFloat(t.netInflowUsd) : null,
    entry_price:  entryPrice,
    target_price: targetPrice,
    stop_price:   stopPrice
  }});
});

return rows;
